let currentLang = 'en';

function applyLanguage(lang) {
    currentLang = lang;
    if (lang === 'th') {
        document.body.classList.add('lang-th');
    } else {
        document.body.classList.remove('lang-th');
    }
    try {
        localStorage.setItem('cod_game_lang', lang);
    } catch (e) {}

    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (i18n[lang][key]) {
            el.textContent = i18n[lang][key];
        }
    });

    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        if (i18n[lang][key]) {
            el.placeholder = i18n[lang][key];
        }
    });

    document.querySelectorAll('[data-i18n-value]').forEach(el => {
        const key = el.getAttribute('data-i18n-value');
        if (i18n[lang][key]) {
            el.value = i18n[lang][key];
        }
    });

    const toggleText = document.getElementById('lang-toggle-text');
    if (toggleText) {
        toggleText.textContent = lang === 'en' ? 'ENGLISH' : 'ไทย';
    }

    const startLobbyBtn = document.getElementById('btn-start-game-lobby');
    if (startLobbyBtn) {
        if (startLobbyBtn.disabled) {
            startLobbyBtn.textContent = i18n[lang].btn_start_game_disabled || (lang === 'th' ? 'เริ่มเกม 🗡️' : 'START GAME 🗡️');
        } else {
            startLobbyBtn.textContent = i18n[lang].btn_start_game || (lang === 'th' ? 'เริ่มเกม 🚀' : 'START GAME 🚀');
        }
    }

    const isFull = typeof expansionGameMode !== 'undefined' && expansionGameMode === 'FULL_DECK';
    const cModeText = document.getElementById('create-mode-text');
    const lModeText = document.getElementById('lobby-mode-text');
    if (cModeText) cModeText.textContent = isFull ? (lang === 'th' ? '🔥 FULL DECK (จัดเต็ม)' : '🔥 FULL DECK MODE') : (lang === 'th' ? '🔥 CLASSIC MODE (ดั้งเดิม)' : '🔥 CLASSIC MODE');
    if (lModeText) lModeText.textContent = isFull ? (lang === 'th' ? '🔥 FULL DECK (จัดเต็ม)' : '🔥 FULL DECK MODE') : (lang === 'th' ? '🔥 CLASSIC MODE (ดั้งเดิม)' : '🔥 CLASSIC MODE');

    if (typeof updateRoleAndObjectiveDisplay === 'function') {
        updateRoleAndObjectiveDisplay();
    }
    if (typeof updatePlayerItemBars === 'function') {
        updatePlayerItemBars();
    }
    if (typeof updateP1DebuffsDisplay === 'function') {
        updateP1DebuffsDisplay();
    }
    if (typeof updateDynamicRuleDisplay === 'function') {
        updateDynamicRuleDisplay();
    }
    if (typeof renderLobbySlots === 'function') {
        const pList = (typeof netClient !== 'undefined' && netClient && netClient.isConnected && netClient.players && netClient.players.length > 0)
            ? netClient.players
            : ((typeof localLobbyPlayers !== 'undefined' && localLobbyPlayers && localLobbyPlayers.length > 0) ? localLobbyPlayers : null);
        if (pList) {
            renderLobbySlots(pList);
        }
    }

    if (typeof renderGuideContent === 'function') {
        const itemGuideModal = document.getElementById('item-guide-modal');
        if (itemGuideModal && itemGuideModal.classList.contains('active')) {
            renderGuideContent(currentGuideTab);
        }
    }
}

// WEB AUDIO API SYSTEM (MASTER GAIN, BGM GAIN, SFX GAIN & PERSISTENCE)
class PixelAudioEngine {
    constructor() {
        this.ctx = null;
        this.masterGain = null;
        this.bgmGain = null;
        this.sfxGain = null;

        // Load saved preferences
        this.masterEnabled = localStorage.getItem('cod_master_audio') !== 'false';
        this.bgmEnabled = localStorage.getItem('cod_bgm_enabled') !== 'false';
        this.sfxEnabled = localStorage.getItem('cod_sfx_enabled') !== 'false';

        this.isPlayingBGM = false;
        this.timer = null;
    }

    init() {
        if (!this.ctx) {
            const AudioContextClass = window.AudioContext || window.webkitAudioContext;
            if (AudioContextClass) {
                this.ctx = new AudioContextClass();

                // Master Gain
                this.masterGain = this.ctx.createGain();
                this.masterGain.connect(this.ctx.destination);
                this.masterGain.gain.setValueAtTime(this.masterEnabled ? 1 : 0, this.ctx.currentTime);

                // BGM Gain
                this.bgmGain = this.ctx.createGain();
                this.bgmGain.connect(this.masterGain);
                this.bgmGain.gain.setValueAtTime(this.bgmEnabled ? 1 : 0, this.ctx.currentTime);

                // SFX Gain
                this.sfxGain = this.ctx.createGain();
                this.sfxGain.connect(this.masterGain);
                this.sfxGain.gain.setValueAtTime(this.sfxEnabled ? 1 : 0, this.ctx.currentTime);
            }
        }
        if (this.ctx && this.ctx.state === 'suspended') {
            this.ctx.resume().catch(() => {});
        }
    }

    setMaster(enabled) {
        this.masterEnabled = !!enabled;
        localStorage.setItem('cod_master_audio', this.masterEnabled);
        if (this.ctx && this.masterGain) {
            this.masterGain.gain.cancelScheduledValues(this.ctx.currentTime);
            this.masterGain.gain.setValueAtTime(this.masterEnabled ? 1 : 0, this.ctx.currentTime);
        }
        if (!this.masterEnabled) {
            this.stopBGM();
        } else if (this.bgmEnabled && !this.isPlayingBGM) {
            this.playBGM();
        }
    }

    setBGM(enabled) {
        this.bgmEnabled = !!enabled;
        localStorage.setItem('cod_bgm_enabled', this.bgmEnabled);
        if (this.ctx && this.bgmGain) {
            this.bgmGain.gain.cancelScheduledValues(this.ctx.currentTime);
            this.bgmGain.gain.setValueAtTime(this.bgmEnabled ? 1 : 0, this.ctx.currentTime);
        }
        if (this.bgmEnabled && this.masterEnabled) {
            this.playBGM();
        } else {
            this.stopBGM();
        }
    }

    setSFX(enabled) {
        this.sfxEnabled = !!enabled;
        localStorage.setItem('cod_sfx_enabled', this.sfxEnabled);
        if (this.ctx && this.sfxGain) {
            this.sfxGain.gain.cancelScheduledValues(this.ctx.currentTime);
            this.sfxGain.gain.setValueAtTime(this.sfxEnabled ? 1 : 0, this.ctx.currentTime);
        }
    }

    playBGM() {
        if (!this.masterEnabled || !this.bgmEnabled) return;
        this.init();
        if (this.isPlayingBGM) return;
        this.isPlayingBGM = true;

        if (this.ctx && this.bgmGain) {
            this.bgmGain.gain.cancelScheduledValues(this.ctx.currentTime);
            this.bgmGain.gain.setValueAtTime(1, this.ctx.currentTime);
        }

        const notes = [261.63, 329.63, 392.00, 523.25, 440.00, 349.23, 392.00, 293.66];
        let step = 0;

        if (this.timer) {
            clearInterval(this.timer);
            this.timer = null;
        }

        this.timer = setInterval(() => {
            if (!this.masterEnabled || !this.bgmEnabled || !this.isPlayingBGM || !this.ctx || !this.bgmGain) return;
            try {
                const osc = this.ctx.createOscillator();
                const gain = this.ctx.createGain();
                
                osc.type = 'triangle';
                osc.frequency.setValueAtTime(notes[step % notes.length], this.ctx.currentTime);
                
                gain.gain.setValueAtTime(0.04, this.ctx.currentTime);
                gain.gain.exponentialRampToValueAtTime(0.0001, this.ctx.currentTime + 0.35);
                
                osc.connect(gain);
                gain.connect(this.bgmGain);
                
                osc.start();
                osc.stop(this.ctx.currentTime + 0.38);
                step++;
            } catch (e) {}
        }, 400);
    }

    stopBGM() {
        this.isPlayingBGM = false;
        if (this.timer) {
            clearInterval(this.timer);
            this.timer = null;
        }
        if (this.ctx && this.bgmGain) {
            this.bgmGain.gain.cancelScheduledValues(this.ctx.currentTime);
            this.bgmGain.gain.setValueAtTime(0, this.ctx.currentTime);
        }
    }

    playClickSFX() {
        if (!this.masterEnabled || !this.sfxEnabled) return;
        this.init();
        if (!this.ctx || !this.sfxGain) return;

        try {
            const osc = this.ctx.createOscillator();
            const gain = this.ctx.createGain();
            
            osc.type = 'square';
            osc.frequency.setValueAtTime(440, this.ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(880, this.ctx.currentTime + 0.08);
            
            gain.gain.setValueAtTime(0.08, this.ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.0001, this.ctx.currentTime + 0.08);
            
            osc.connect(gain);
            gain.connect(this.sfxGain);
            
            osc.start();
            osc.stop(this.ctx.currentTime + 0.08);
        } catch (e) {}
    }

    playCardPlaySFX() {
        if (!this.masterEnabled || !this.sfxEnabled) return;
        this.init();
        if (!this.ctx || !this.sfxGain) return;

        try {
            const osc = this.ctx.createOscillator();
            const gain = this.ctx.createGain();

            osc.type = 'triangle';
            osc.frequency.setValueAtTime(540, this.ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(120, this.ctx.currentTime + 0.12);

            gain.gain.setValueAtTime(0.12, this.ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.12);

            osc.connect(gain);
            gain.connect(this.sfxGain);

            osc.start();
            osc.stop(this.ctx.currentTime + 0.12);
        } catch (e) {}
    }

    playBluffFailSFX() {
        if (!this.masterEnabled || !this.sfxEnabled) return;
        this.init();
        if (!this.ctx || !this.sfxGain) return;

        try {
            const notes = [280, 210, 150];
            notes.forEach((freq, idx) => {
                const osc = this.ctx.createOscillator();
                const gain = this.ctx.createGain();
                osc.type = 'sawtooth';
                osc.frequency.setValueAtTime(freq, this.ctx.currentTime + idx * 0.1);

                gain.gain.setValueAtTime(0.08, this.ctx.currentTime + idx * 0.1);
                gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + idx * 0.1 + 0.14);

                osc.connect(gain);
                gain.connect(this.sfxGain);

                osc.start(this.ctx.currentTime + idx * 0.1);
                osc.stop(this.ctx.currentTime + idx * 0.1 + 0.14);
            });
        } catch (e) {}
    }

    playBluffCaughtSFX() {
        if (!this.masterEnabled || !this.sfxEnabled) return;
        this.init();
        if (!this.ctx || !this.sfxGain) return;

        try {
            const notes = [523.25, 659.25, 783.99, 1046.50];
            notes.forEach((freq, idx) => {
                const osc = this.ctx.createOscillator();
                const gain = this.ctx.createGain();
                osc.type = 'square';
                osc.frequency.setValueAtTime(freq, this.ctx.currentTime + idx * 0.08);

                gain.gain.setValueAtTime(0.07, this.ctx.currentTime + idx * 0.08);
                gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + idx * 0.08 + 0.12);

                osc.connect(gain);
                gain.connect(this.sfxGain);

                osc.start(this.ctx.currentTime + idx * 0.08);
                osc.stop(this.ctx.currentTime + idx * 0.08 + 0.12);
            });
        } catch (e) {}
    }

    playTruthSFX() {
        if (!this.masterEnabled || !this.sfxEnabled) return;
        this.init();
        if (!this.ctx || !this.sfxGain) return;

        try {
            [150, 160].forEach(freq => {
                const osc = this.ctx.createOscillator();
                const gain = this.ctx.createGain();
                osc.type = 'sawtooth';
                osc.frequency.setValueAtTime(freq, this.ctx.currentTime);

                gain.gain.setValueAtTime(0.08, this.ctx.currentTime);
                gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.28);

                osc.connect(gain);
                gain.connect(this.sfxGain);

                osc.start();
                osc.stop(this.ctx.currentTime + 0.28);
            });
        } catch (e) {}
    }

    playVictorySFX() {
        if (!this.masterEnabled || !this.sfxEnabled) return;
        this.init();
        if (!this.ctx || !this.sfxGain) return;

        try {
            const fanfare = [
                { f: 523.25, d: 0.12, t: 0.00 },
                { f: 659.25, d: 0.12, t: 0.12 },
                { f: 783.99, d: 0.14, t: 0.24 },
                { f: 1046.50, d: 0.35, t: 0.38 },
                { f: 880.00, d: 0.14, t: 0.74 },
                { f: 1046.50, d: 0.50, t: 0.90 }
            ];
            fanfare.forEach(note => {
                const osc = this.ctx.createOscillator();
                const gain = this.ctx.createGain();
                osc.type = 'triangle';
                osc.frequency.setValueAtTime(note.f, this.ctx.currentTime + note.t);

                gain.gain.setValueAtTime(0.09, this.ctx.currentTime + note.t);
                gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + note.t + note.d);

                osc.connect(gain);
                gain.connect(this.sfxGain);

                osc.start(this.ctx.currentTime + note.t);
                osc.stop(this.ctx.currentTime + note.t + note.d);
            });
        } catch (e) {}
    }

    playSkillSFX() {
        if (!this.masterEnabled || !this.sfxEnabled) return;
        this.init();
        if (!this.ctx || !this.sfxGain) return;
        try {
            [440, 554.37, 659.25, 880].forEach((freq, idx) => {
                const osc = this.ctx.createOscillator();
                const gain = this.ctx.createGain();
                osc.type = 'triangle';
                osc.frequency.setValueAtTime(freq, this.ctx.currentTime + idx * 0.07);
                gain.gain.setValueAtTime(0.09, this.ctx.currentTime + idx * 0.07);
                gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + idx * 0.07 + 0.2);
                osc.connect(gain);
                gain.connect(this.sfxGain);
                osc.start(this.ctx.currentTime + idx * 0.07);
                osc.stop(this.ctx.currentTime + idx * 0.07 + 0.2);
            });
        } catch (e) {}
    }

    playShieldBlockSFX() {
        if (!this.masterEnabled || !this.sfxEnabled) return;
        this.init();
        if (!this.ctx || !this.sfxGain) return;
        try {
            const osc = this.ctx.createOscillator();
            const gain = this.ctx.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(800, this.ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(300, this.ctx.currentTime + 0.25);
            gain.gain.setValueAtTime(0.15, this.ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.25);
            osc.connect(gain);
            gain.connect(this.sfxGain);
            osc.start();
            osc.stop(this.ctx.currentTime + 0.25);
        } catch (e) {}
    }

    playHackerSFX() {
        if (!this.masterEnabled || !this.sfxEnabled) return;
        this.init();
        if (!this.ctx || !this.sfxGain) return;
        try {
            [900, 1200, 800, 1400, 1600].forEach((freq, idx) => {
                const osc = this.ctx.createOscillator();
                const gain = this.ctx.createGain();
                osc.type = 'sawtooth';
                osc.frequency.setValueAtTime(freq, this.ctx.currentTime + idx * 0.04);
                gain.gain.setValueAtTime(0.05, this.ctx.currentTime + idx * 0.04);
                gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + idx * 0.04 + 0.08);
                osc.connect(gain);
                gain.connect(this.sfxGain);
                osc.start(this.ctx.currentTime + idx * 0.04);
                osc.stop(this.ctx.currentTime + idx * 0.04 + 0.08);
            });
        } catch (e) {}
    }

    playPenaltyDrawSFX() {
        if (!this.masterEnabled || !this.sfxEnabled) return;
        this.init();
        if (!this.ctx || !this.sfxGain) return;
        try {
            const osc = this.ctx.createOscillator();
            const gain = this.ctx.createGain();
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(220, this.ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(70, this.ctx.currentTime + 0.4);
            gain.gain.setValueAtTime(0.12, this.ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.4);
            osc.connect(gain);
            gain.connect(this.sfxGain);
            osc.start();
            osc.stop(this.ctx.currentTime + 0.4);
        } catch (e) {}
    }

    playTickSFX() {
        if (!this.masterEnabled || !this.sfxEnabled) return;
        this.init();
        if (!this.ctx || !this.sfxGain) return;
        try {
            const osc = this.ctx.createOscillator();
            const gain = this.ctx.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(880, this.ctx.currentTime);
            gain.gain.setValueAtTime(0.06, this.ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.05);
            osc.connect(gain);
            gain.connect(this.sfxGain);
            osc.start();
            osc.stop(this.ctx.currentTime + 0.05);
        } catch (e) {}
    }

    playTimeoutSFX() {
        if (!this.masterEnabled || !this.sfxEnabled) return;
        this.init();
        if (!this.ctx || !this.sfxGain) return;
        try {
            [160, 130, 100].forEach((freq, idx) => {
                const osc = this.ctx.createOscillator();
                const gain = this.ctx.createGain();
                osc.type = 'sawtooth';
                osc.frequency.setValueAtTime(freq, this.ctx.currentTime + idx * 0.08);
                gain.gain.setValueAtTime(0.14, this.ctx.currentTime + idx * 0.08);
                gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + idx * 0.08 + 0.25);
                osc.connect(gain);
                gain.connect(this.sfxGain);
                osc.start(this.ctx.currentTime + idx * 0.08);
                osc.stop(this.ctx.currentTime + idx * 0.08 + 0.25);
            });
        } catch (e) {}
    }

    playCardDealSFX(index = 0) {
        if (!this.masterEnabled || !this.sfxEnabled) return;
        this.init();
        if (!this.ctx || !this.sfxGain) return;
        try {
            const osc = this.ctx.createOscillator();
            const gain = this.ctx.createGain();
            const baseFreq = 580 + (index % 6) * 35 + (Math.random() * 25);
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(baseFreq, this.ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(160, this.ctx.currentTime + 0.07);

            gain.gain.setValueAtTime(0.08, this.ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.07);

            osc.connect(gain);
            gain.connect(this.sfxGain);

            osc.start();
            osc.stop(this.ctx.currentTime + 0.07);
        } catch (e) {}
    }

    playCardSettleSFX() {
        if (!this.masterEnabled || !this.sfxEnabled) return;
        this.init();
        if (!this.ctx || !this.sfxGain) return;
        try {
            [330, 440, 660].forEach((freq, idx) => {
                const osc = this.ctx.createOscillator();
                const gain = this.ctx.createGain();
                osc.type = 'sine';
                osc.frequency.setValueAtTime(freq, this.ctx.currentTime + idx * 0.03);
                gain.gain.setValueAtTime(0.06, this.ctx.currentTime + idx * 0.03);
                gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + idx * 0.03 + 0.15);
                osc.connect(gain);
                gain.connect(this.sfxGain);
                osc.start(this.ctx.currentTime + idx * 0.03);
                osc.stop(this.ctx.currentTime + idx * 0.03 + 0.15);
            });
        } catch (e) {}
    }

    playHeartBreakSFX() {
        if (!this.masterEnabled || !this.sfxEnabled) return;
        this.init();
        if (!this.ctx || !this.sfxGain) return;
        try {
            const now = this.ctx.currentTime;
            
            // 1. Heavy low-end impact punch
            const subOsc = this.ctx.createOscillator();
            const subGain = this.ctx.createGain();
            subOsc.type = 'sine';
            subOsc.frequency.setValueAtTime(160, now);
            subOsc.frequency.exponentialRampToValueAtTime(35, now + 0.35);
            subGain.gain.setValueAtTime(0.25, now);
            subGain.gain.exponentialRampToValueAtTime(0.001, now + 0.35);
            subOsc.connect(subGain);
            subGain.connect(this.sfxGain);
            subOsc.start(now);
            subOsc.stop(now + 0.35);

            // 2. Crisp jagged crack / crunch
            const crackOsc = this.ctx.createOscillator();
            const crackGain = this.ctx.createGain();
            crackOsc.type = 'sawtooth';
            crackOsc.frequency.setValueAtTime(850, now);
            crackOsc.frequency.linearRampToValueAtTime(140, now + 0.09);
            crackGain.gain.setValueAtTime(0.2, now);
            crackGain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);
            crackOsc.connect(crackGain);
            crackGain.connect(this.sfxGain);
            crackOsc.start(now);
            crackOsc.stop(now + 0.12);

            // 3. Crystal shards clinking / dispersing
            const crystalFreqs = [1760, 2349, 3136, 1975];
            crystalFreqs.forEach((freq, idx) => {
                const cOsc = this.ctx.createOscillator();
                const cGain = this.ctx.createGain();
                const startT = now + 0.03 + idx * 0.04;
                cOsc.type = 'triangle';
                cOsc.frequency.setValueAtTime(freq, startT);
                cOsc.frequency.exponentialRampToValueAtTime(freq * 0.65, startT + 0.18);
                cGain.gain.setValueAtTime(0.09, startT);
                cGain.gain.exponentialRampToValueAtTime(0.001, startT + 0.18);
                cOsc.connect(cGain);
                cGain.connect(this.sfxGain);
                cOsc.start(startT);
                cOsc.stop(startT + 0.18);
            });
        } catch (e) {}
    }
}

// REAL-TIME WEBSOCKET NETWORK CLIENT
class NetworkClient {
    constructor() {
        this.ws = null;
        this.isConnected = false;
        this.isHost = false;
        this.roomCode = null;
        this.myId = null;
        this.myName = '';
        this.myCharId = '1';
        this.players = [];
        this.handlers = {};
    }

    connect(onStatusChange) {
        if (this.ws && (this.ws.readyState === WebSocket.OPEN || this.ws.readyState === WebSocket.CONNECTING)) {
            return;
        }

        const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
        const host = window.location.host || 'localhost:3000';
        const wsUrl = `${protocol}//${host}`;

        try {
            this.ws = new WebSocket(wsUrl);

            this.ws.onopen = () => {
                this.isConnected = true;
                if (onStatusChange) onStatusChange(true);
                console.log('Connected to multiplayer server at', wsUrl);
            };

            this.ws.onmessage = (event) => {
                try {
                    const data = JSON.parse(event.data);
                    if (this.handlers[data.type]) {
                        this.handlers[data.type](data);
                    }
                } catch (e) {
                    console.error('WS parse error:', e);
                }
            };

            this.ws.onclose = () => {
                this.isConnected = false;
                if (onStatusChange) onStatusChange(false);
                // Attempt reconnect after 3s
                setTimeout(() => this.connect(onStatusChange), 3000);
            };

            this.ws.onerror = (err) => {
                this.isConnected = false;
                if (onStatusChange) onStatusChange(false);
            };
        } catch (e) {
            this.isConnected = false;
            if (onStatusChange) onStatusChange(false);
        }
    }

    on(type, callback) {
        this.handlers[type] = callback;
    }

    send(data) {
        if (this.ws && this.ws.readyState === WebSocket.OPEN) {
            this.ws.send(JSON.stringify(data));
        }
    }
}

