    const btnDeviceCopyLink = document.getElementById('btn-device-copy-link');
    const deviceModalRoomCode = document.getElementById('device-modal-room-code');
    const btnCloseDeviceModal = document.getElementById('btn-close-device-modal');
    const deviceIpSelect = document.getElementById('device-ip-select');
    const deviceIpSelectRow = document.getElementById('device-ip-select-row');

    let serverLanIps = [];
    let serverPrimaryIp = (window.location.hostname && window.location.hostname !== 'localhost' && window.location.hostname !== '127.0.0.1') ? window.location.hostname : '';
    let serverPort = window.location.port || '3000';
    let activeRoomCodeForDeviceModal = 'COD-8899';

    function fetchServerNetworkInfo() {
        fetch('/api/network-info')
            .then(res => res.json())
            .then(data => {
                if (data && data.ips && data.ips.length > 0) {
                    serverLanIps = data.ips;
                    if (!serverPrimaryIp) {
                        serverPrimaryIp = data.primaryIp || data.ips[0];
                    }
                    serverPort = data.port || serverPort;
                    updateDeviceIpSelect();
                }
            })
            .catch(() => {});
    }

    function updateDeviceIpSelect() {
        if (!deviceIpSelect) return;
        deviceIpSelect.innerHTML = '';
        if (serverLanIps.length > 1 && deviceIpSelectRow) {
            deviceIpSelectRow.style.display = 'flex';
        } else if (deviceIpSelectRow) {
            deviceIpSelectRow.style.display = 'none';
        }
        serverLanIps.forEach(ip => {
            const opt = document.createElement('option');
            opt.value = ip;
            opt.textContent = ip;
            if (ip === serverPrimaryIp) opt.selected = true;
            deviceIpSelect.appendChild(opt);
        });
        deviceIpSelect.onchange = () => {
            serverPrimaryIp = deviceIpSelect.value;
            renderDeviceModalQrCode(activeRoomCodeForDeviceModal);
        };
    }

    function getDeviceJoinUrl(roomCode) {
        const hostIp = serverPrimaryIp || window.location.hostname || 'localhost';
        const portStr = serverPort ? `:${serverPort}` : '';
        const protocol = window.location.protocol || 'http:';
        const code = roomCode || activeRoomCodeForDeviceModal || 'COD-8899';
        return `${protocol}//${hostIp}${portStr}/?room=${encodeURIComponent(code)}`;
    }

    function renderDeviceModalQrCode(roomCode) {
        activeRoomCodeForDeviceModal = roomCode || activeRoomCodeForDeviceModal;
        const joinUrl = getDeviceJoinUrl(activeRoomCodeForDeviceModal);
        if (deviceJoinUrlInput) deviceJoinUrlInput.value = joinUrl;
        if (deviceModalRoomCode) deviceModalRoomCode.textContent = activeRoomCodeForDeviceModal;

        if (deviceQrImage) {
            if (deviceQrLoading) deviceQrLoading.style.display = 'block';
            deviceQrImage.style.display = 'none';
            deviceQrImage.onload = () => {
                if (deviceQrLoading) deviceQrLoading.style.display = 'none';
                deviceQrImage.style.display = 'block';
            };
            deviceQrImage.onerror = () => {
                if (deviceQrLoading) {
                    deviceQrLoading.textContent = joinUrl;
                    deviceQrLoading.style.display = 'block';
                }
            };
            deviceQrImage.src = `/api/qrcode?text=${encodeURIComponent(joinUrl)}`;
            deviceQrImage.alt = `Scan QR Code to join room ${activeRoomCodeForDeviceModal}`;
        }
    }

    function openDeviceJoinModal(roomCode) {
        audioEngine.playClickSFX();
        activeRoomCodeForDeviceModal = roomCode || document.getElementById('generated-room-code')?.value || lobbyRoomCodeDisplay?.textContent || 'COD-8899';
        renderDeviceModalQrCode(activeRoomCodeForDeviceModal);
        if (deviceJoinModal) deviceJoinModal.classList.add('active');
    }

    function closeDeviceJoinModal() {
        audioEngine.playClickSFX();
        if (deviceJoinModal) deviceJoinModal.classList.remove('active');
    }

    function toggleFullscreen() {
        audioEngine.playClickSFX();
        if (!document.fullscreenElement && !document.webkitFullscreenElement) {
            const el = document.documentElement;
            if (el.requestFullscreen) {
                el.requestFullscreen().catch(() => {});
            } else if (el.webkitRequestFullscreen) {
                el.webkitRequestFullscreen().catch(() => {});
            }
            showToast(currentLang === 'th' ? 'เปิดโหมดเต็มหน้าจอ' : 'Entered Fullscreen');
        } else {
            if (document.exitFullscreen) {
                document.exitFullscreen().catch(() => {});
            } else if (document.webkitExitFullscreen) {
                document.webkitExitFullscreen().catch(() => {});
            }
            showToast(currentLang === 'th' ? 'ออกจากโหมดเต็มหน้าจอ' : 'Exited Fullscreen');
        }
    }

    function updateSidebarBackdrop() {
        if (!sidebarBackdrop) return;
        const isMobileOrTablet = window.innerWidth <= 1080;
        const isRightOpen = gpRightInfoBox && !gpRightInfoBox.classList.contains('collapsed');
        const isLeftOpen = gpLeftItemBox && !gpLeftItemBox.classList.contains('collapsed');
        if (isMobileOrTablet && (isRightOpen || isLeftOpen)) {
            sidebarBackdrop.style.display = 'block';
        } else {
            sidebarBackdrop.style.display = 'none';
        }
    }

    function unlockAudioOnFirstInteraction() {
        const unlock = () => {
            audioEngine.init();
            window.removeEventListener('touchstart', unlock, true);
            window.removeEventListener('touchend', unlock, true);
            window.removeEventListener('pointerdown', unlock, true);
            window.removeEventListener('click', unlock, true);
        };
        window.addEventListener('touchstart', unlock, { capture: true, passive: true });
        window.addEventListener('touchend', unlock, { capture: true, passive: true });
        window.addEventListener('pointerdown', unlock, { capture: true, passive: true });
        window.addEventListener('click', unlock, { capture: true, passive: true });
    }

