    function updateDynamicRuleDisplay() {
        if (!currentDynamicRule) return;
        const iconEl = document.getElementById('dyn-rule-icon');
        const textEl = document.getElementById('dyn-rule-text');
        const descEl = document.getElementById('dyn-rule-desc');
        const bannerEl = document.getElementById('dynamic-rule-banner');

        const isTh = currentLang === 'th';
        let rName = '';
        if (isTh) {
            if (currentDynamicRule.nameTh && currentDynamicRule.name && currentDynamicRule.nameTh !== currentDynamicRule.name) {
                rName = `${currentDynamicRule.nameTh} (${currentDynamicRule.name})`;
            } else {
                rName = currentDynamicRule.nameTh || currentDynamicRule.name || 'Standard Duel';
            }
        } else {
            rName = currentDynamicRule.name || currentDynamicRule.nameTh || 'Standard Duel';
        }

        const rDesc = isTh
            ? (currentDynamicRule.descTh || currentDynamicRule.desc || currentDynamicRule.descEn)
            : (currentDynamicRule.desc || currentDynamicRule.descEn || currentDynamicRule.descTh);

        if (iconEl) iconEl.textContent = currentDynamicRule.icon || '🎲';
        if (textEl) textEl.textContent = rName;
        if (descEl) descEl.textContent = rDesc || 'Standard rules apply. Play 1-3 cards normally.';
        if (bannerEl) {
            bannerEl.style.display = 'inline-flex';
            bannerEl.title = `${rName}: ${rDesc} (Click for details)`;
        }
    }

    // Local offline bot mode state
    let localRoles = [];
    let localShields = [false, false, false, false];
    let localSkillsUsed = [false, false, false, false];
    let localSuspicion = [50, 50, 50, 50];
    let localBluffHistory = [{ total: 0, bluffs: 0 }, { total: 0, bluffs: 0 }, { total: 0, bluffs: 0 }, { total: 0, bluffs: 0 }];
    let localUncaughtBluffs = [0, 0, 0, 0];
    let localCaughtCounts = [0, 0, 0, 0];
    let localSecretObjectives = [];
    let localDrawPile = [];

    function updateModeUI(mode) {
        expansionGameMode = mode || 'CLASSIC';
        const isFull = expansionGameMode === 'FULL_DECK';
        if (createModeText) {
            createModeText.textContent = isFull 
                ? (currentLang === 'th' ? '🔥 FULL DECK (จัดเต็ม)' : '🔥 FULL DECK MODE') 
                : (currentLang === 'th' ? '🔥 CLASSIC MODE (ดั้งเดิม)' : '🔥 CLASSIC MODE');
        }
        if (lobbyModeText) {
            lobbyModeText.textContent = isFull 
                ? (currentLang === 'th' ? '🔥 FULL DECK (จัดเต็ม)' : '🔥 FULL DECK MODE') 
                : (currentLang === 'th' ? '🔥 CLASSIC MODE (ดั้งเดิม)' : '🔥 CLASSIC MODE');
        }

        if (createModeToggle) {
            createModeToggle.style.borderColor = isFull ? '#ffd700' : '#450a0a';
            createModeToggle.style.boxShadow = isFull ? '0 0 10px rgba(255, 215, 0, 0.4)' : '';
        }
        if (lobbyModeToggle) {
            lobbyModeToggle.style.borderColor = isFull ? '#ffd700' : '#450a0a';
            lobbyModeToggle.style.boxShadow = isFull ? '0 0 10px rgba(255, 215, 0, 0.4)' : '';
        }
    }

    if (createModeToggle) {
        createModeToggle.addEventListener('click', () => {
            audioEngine.playClickSFX();
            const nextMode = expansionGameMode === 'FULL_DECK' ? 'CLASSIC' : 'FULL_DECK';
            updateModeUI(nextMode);
            showToast(currentLang === 'th' 
                ? (nextMode === 'FULL_DECK' ? '🔥 เปลี่ยนเป็น FULL DECK (ไพ่ 2-10, J, Q, K, A - ลงไพ่แล้วสุ่มจั่วขึ้นมือ 1 ใบ)' : '⚔️ เปลี่ยนเป็น CLASSIC MODE (ไพ่ K, Q, J, A - ไม่จั่วไพ่เพิ่ม)')
                : (nextMode === 'FULL_DECK' ? '🔥 Switched to FULL DECK (Cards 2-10, J, Q, K, A - draw 1 card on play)' : '⚔️ Switched to CLASSIC MODE (Cards K, Q, J, A - no draw on play)'));
            if (netClient.isConnected && netClient.isHost) {
                netClient.send({ type: 'SET_GAME_MODE', mode: nextMode });
            }
        });
    }

    if (lobbyModeToggle) {
        lobbyModeToggle.addEventListener('click', () => {
            audioEngine.playClickSFX();
            if (netClient.isConnected && !netClient.isHost) {
                showToast(currentLang === 'th' ? 'เฉพาะโฮสต์เท่านั้นที่เปลี่ยนโหมดได้!' : 'Only Host can change game mode!');
                return;
            }
            const nextMode = expansionGameMode === 'FULL_DECK' ? 'CLASSIC' : 'FULL_DECK';
            updateModeUI(nextMode);
            showToast(currentLang === 'th' 
                ? (nextMode === 'FULL_DECK' ? '🔥 เปลี่ยนเป็น FULL DECK (ไพ่ 2-10, J, Q, K, A - ลงไพ่แล้วสุ่มจั่วขึ้นมือ 1 ใบ)' : '⚔️ เปลี่ยนเป็น CLASSIC MODE (ไพ่ K, Q, J, A - ไม่จั่วไพ่เพิ่ม)')
                : (nextMode === 'FULL_DECK' ? '🔥 Switched to FULL DECK (Cards 2-10, J, Q, K, A - draw 1 card on play)' : '⚔️ Switched to CLASSIC MODE (Cards K, Q, J, A - no draw on play)'));
            if (netClient.isConnected && netClient.isHost) {
                netClient.send({ type: 'SET_GAME_MODE', mode: nextMode });
            }
        });
    }

