    // Opponent seat clicks for item target selection (seats 2, 3, 4)
    for (let sIdx = 1; sIdx <= 3; sIdx++) {
        const seat = document.getElementById(`gp-seat-${sIdx + 1}`);
        if (seat) {
            seat.addEventListener('click', (e) => {
                if (isItemTargetSelectionMode) {
                    e.stopPropagation();
                    handleSeatTargetClick(sIdx);
                }
            });
        }
    }

    if (btnCloseIntel) {
        btnCloseIntel.addEventListener('click', () => {
            audioEngine.playClickSFX();
            if (intelModal) intelModal.classList.remove('active');
        });
    }

    if (btnRoleSkill) {
        btnRoleSkill.addEventListener('click', () => {
            audioEngine.playClickSFX();
            if (roleSkillUsed) {
                showToast(currentLang === 'th' ? 'คุณใช้สกิลประจำตัวไปแล้วในเกมนี้!' : 'Skill already used this game!');
                return;
            }

            if (!myRole) {
                showToast(currentLang === 'th' ? 'คุณยังไม่มีบทบาทตัวละคร!' : 'No character role assigned!');
                return;
            }

            if (myRole.id === 'gambler') {
                audioEngine.playSkillSFX();
                showToast(currentLang === 'th'
                    ? '🎲 สกิล Gambler (ติดตัว): เมื่อกดจับโกหกสำเร็จจะได้ +1 HP ❤️ แต่ถ้าทายผิดจะสุ่มทำลายไอเทม 1 ชิ้นในมือแทน (ถ้าไอเทมหมดจะเสีย 1 HP)'
                    : '🎲 Gambler (Passive): Triggers on CALL BLUFF. Success gives +1 HP ❤️, failure randomly destroys 1 item in hand (or loses 1 HP if no items left).');
                return;
            }

            if (netClient.isConnected) {
                let selectedId = null;
                if (myRole.id === 'trickster') {
                    if (!isMyOnlineTurn()) {
                        showToast(currentLang === 'th' ? 'ใช้สกิล Trickster ได้เฉพาะในตาของตนเองเท่านั้น!' : 'Can only use Trickster skill on your turn!');
                        return;
                    }
                    if (p1Selected.length > 0) {
                        selectedId = p1CardObjects[p1Selected[0]]?.id;
                    } else if (p1CardObjects && p1CardObjects.length > 0) {
                        selectedId = p1CardObjects[0].id;
                    }
                }

                netClient.send({
                    type: 'USE_ROLE_SKILL',
                    cardId: selectedId
                });
            } else {
                handleLocalRoleSkill();
            }
        });
    }

    let selectedCharacter = '1';
    let lobbyPlayerCount = 1;

    // Connect to WebSocket Server and update badge
    netClient.connect((connected) => {
        if (netStatusDot && netStatusText) {
            if (connected) {
                netStatusDot.style.background = '#00ff88';
                netStatusText.textContent = 'ONLINE SERVER';
                netStatusText.style.color = '#00ff88';
            } else {
                netStatusDot.style.background = '#ff4444';
                netStatusText.textContent = 'LOCAL OFFLINE';
                netStatusText.style.color = '#a88967';
            }
        }
    });

    document.body.addEventListener('click', () => {
        audioEngine.playBGM();
    }, { once: true });

    // SETTINGS HANDLERS
    function openSettings() {
        audioEngine.playClickSFX();
        settingsModal.classList.add('active');
    }

    if (btnCornerSettings) btnCornerSettings.addEventListener('click', openSettings);
    if (btnCornerSettingsLobby) btnCornerSettingsLobby.addEventListener('click', openSettings);

    if (btnCloseSettings) {
        btnCloseSettings.addEventListener('click', () => {
            audioEngine.playClickSFX();
            settingsModal.classList.remove('active');
        });
    }

    if (btnLangToggle) {
        btnLangToggle.addEventListener('click', () => {
            audioEngine.playClickSFX();
            const nextLang = currentLang === 'en' ? 'th' : 'en';
            applyLanguage(nextLang);
        });
    }

    // COMPREHENSIVE GAME GUIDE MODAL HANDLERS
